@extends('layouts.app') @section('content')<div class="card"><h1>{{ $task->exists ? 'Edit Task' : 'Create Task' }}</h1><form method="POST" action="{{ $task->exists ? route('tasks.update',$task) : route('tasks.store') }}">@csrf @if($task->exists) @method('PUT') @endif<label>Title</label><input name="title" value="{{ old('title',$task->title) }}" maxlength="150" required><label>Date</label><input type="date" name="task_date" value="{{ old('task_date',optional($task->task_date)->format('Y-m-d')) }}" required><label>Status</label><select name="status">@foreach(['pending','in progress','done'] as $status)<option value="{{ $status }}" @selected(old('status',$task->status)===$status)>{{ ucfirst($status) }}</option>@endforeach</select><button>{{ $task->exists ? 'Save Changes' : 'Create Task' }}</button> <a class="btn secondary" href="{{ route('tasks.index') }}">Cancel</a></form></div>@endsection
